INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff146d22-ca35-4d0c-aa68-9b512dc84464', '祭汾陰樂章', '祭汾阴乐章', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u79ae\\u7269\\u65af\\u5177\\uff0c\\u6a02\\u7ae0\\u4e43\\u9673\\u3002\", \"\\u8ab0\\u5176\\u4f5c\\u4e3b\\uff0c\\u7687\\u8003\\u8056\\u771f\\u3002\", \"\\u5c0d\\u8d8a\\u5728\\u5929\\uff0c\\u8056\\u660e\\u4f50\\u795e\\u3002\", \"\\u7a85\\u7136\\u6c7e\\u4e0a\\uff0c\\u539a\\u6fa4\\u5982\\u6625\\u3002\"]"', '"[\"\\u793c\\u7269\\u65af\\u5177\\uff0c\\u4e50\\u7ae0\\u4e43\\u9648\\u3002\", \"\\u8c01\\u5176\\u4f5c\\u4e3b\\uff0c\\u7687\\u8003\\u5723\\u771f\\u3002\", \"\\u5bf9\\u8d8a\\u5728\\u5929\\uff0c\\u5723\\u660e\\u4f50\\u795e\\u3002\", \"\\u7a85\\u7136\\u6c7e\\u4e0a\\uff0c\\u539a\\u6cfd\\u5982\\u6625\\u3002\"]"', '诗', 'shi', '', NULL, '祭汾陰樂章');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0e1958-1b2f-4c25-b013-4c68913fba30', '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制', '奉和圣制行次成皐途经先圣擒建德之所感而成诗应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6f22\\u6771\\u4e0d\\u57f7\\u8c61\\uff0c\\u6cb3\\u6714\\u65b9\\u9b2c\\u9f8d\\u3002\", \"\\u590f\\u6ec5\\u6f38\\u5be7\\u4e82\\uff0c\\u5510\\u8208\\u7d42\\u596e\\u5eb8\\u3002\", \"\\u7687\\u5a01\\u6b63\\u8d6b\\u8d6b\\uff0c\\u5175\\u6c23\\u4f55\\u5308\\u5308\\u3002\", \"\\u7528\\u6b66\\u4e09\\u5ddd\\u9707\\uff0c\\u6b78\\u6df3\\u516d\\u4ee3\\u91b2\\u3002\", \"\\u6210\\u81ef\\u89a9\\u738b\\u696d\\uff0c\\u5929\\u4e0b\\u81f4\\u4eba\\u96cd\\u3002\", \"\\u5373\\u6b64\\u5de1\\u65bc\\u5cb1\\uff0c\\u66fe\\u5b6b\\u53d7\\u547d\\u5c01\\u3002\"]"', '"[\"\\u6c49\\u4e1c\\u4e0d\\u6267\\u8c61\\uff0c\\u6cb3\\u6714\\u65b9\\u9b2c\\u9f99\\u3002\", \"\\u590f\\u706d\\u6e10\\u5b81\\u4e71\\uff0c\\u5510\\u5174\\u7ec8\\u594b\\u5eb8\\u3002\", \"\\u7687\\u5a01\\u6b63\\u8d6b\\u8d6b\\uff0c\\u5175\\u6c14\\u4f55\\u5308\\u5308\\u3002\", \"\\u7528\\u6b66\\u4e09\\u5ddd\\u9707\\uff0c\\u5f52\\u6df3\\u516d\\u4ee3\\ud872\\udea9\\u3002\", \"\\u6210\\u81ef\\u89a9\\u738b\\u4e1a\\uff0c\\u5929\\u4e0b\\u81f4\\u4eba\\u96cd\\u3002\", \"\\u5373\\u6b64\\u5de1\\u4e8e\\u5cb1\\uff0c\\u66fe\\u5b59\\u53d7\\u547d\\u5c01\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d81c2f90-7a7b-455e-a3f2-389d5f3e7fbf', '奉和聖製登蒲州逍遙樓應制', '奉和圣制登蒲州逍遥楼应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5728\\u6614\\u582f\\u821c\\u79b9\\uff0c\\u907a\\u5875\\u6210\\u5178\\u8b28\\u3002\", \"\\u8056\\u7687\\u6771\\u5de1\\u72e9\\uff0c\\u6cc1\\u4e43\\u7d93\\u6b64\\u90fd\\u3002\", \"\\u6a13\\u89c0\\u7d1b\\u8fe4\\u9090\\uff0c\\u6cb3\\u5c71\\u5e7e\\u7e08\\u7d06\\u3002\", \"\\u7dec\\u61f7\\u7956\\u5b97\\u696d\\uff0c\\u76f8\\u7e7c\\u6587\\u6b66\\u5716\\u3002\", \"\\u5c1a\\u5fb7\\u65e2\\u7121\\u96aa\\uff0c\\u89c0\\u98a8\\u8ad2\\u6709\\u5b5a\\u3002\", \"\\u8c48\\u5982\\u6c7e\\u6c34\\u4e0a\\uff0c\\u7c2b\\u9f13\\u4e8b\\u904a\\u5a1b\\u3002\"]"', '"[\"\\u5728\\u6614\\u5c27\\u821c\\u79b9\\uff0c\\u9057\\u5c18\\u6210\\u5178\\u8c1f\\u3002\", \"\\u5723\\u7687\\u4e1c\\u5de1\\u72e9\\uff0c\\u51b5\\u4e43\\u7ecf\\u6b64\\u90fd\\u3002\", \"\\u697c\\u89c2\\u7eb7\\u8fe4\\u9026\\uff0c\\u6cb3\\u5c71\\u51e0\\u8426\\u7ea1\\u3002\", \"\\u7f05\\u6000\\u7956\\u5b97\\u4e1a\\uff0c\\u76f8\\u7ee7\\u6587\\u6b66\\u56fe\\u3002\", \"\\u5c1a\\u5fb7\\u65e2\\u65e0\\u9669\\uff0c\\u89c2\\u98ce\\u8c05\\u6709\\u5b5a\\u3002\", \"\\u5c82\\u5982\\u6c7e\\u6c34\\u4e0a\\uff0c\\u7bab\\u9f13\\u4e8b\\u6e38\\u5a31\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製登蒲州逍遙樓應制');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b2d165-05e6-418f-8a3a-f80872851807', '幸白鹿觀應制', '幸白鹿观应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u78a7\\u865b\\u6e05\\u5439\\u4e0b\\uff0c\\u85f9\\u85f9\\u5165\\u4ed9\\u5bae\\u3002\", \"\\u677e\\u78f4\\u6500\\u96f2\\u7d55\\uff0c\\u82b1\\u6e90\\u63a5\\u6f97\\u7a7a\\u3002\", \"\\u53d7\\u7b26\\u9080\\u7fbd\\u4f7f\\uff0c\\u50b3\\u8a23\\u6ce8\\u9999\\u7ae5\\u3002\", \"\\u8a4e\\u4f3c\\u9591\\u5c45\\u65e5\\uff0c\\u5f92\\u805e\\u6709\\u9806\\u98a8\\u3002\"]"', '"[\"\\u78a7\\u865a\\u6e05\\u5439\\u4e0b\\uff0c\\u853c\\u853c\\u5165\\u4ed9\\u5bab\\u3002\", \"\\u677e\\u78f4\\u6500\\u4e91\\u7edd\\uff0c\\u82b1\\u6e90\\u63a5\\u6da7\\u7a7a\\u3002\", \"\\u53d7\\u7b26\\u9080\\u7fbd\\u4f7f\\uff0c\\u4f20\\u8bc0\\u6ce8\\u9999\\u7ae5\\u3002\", \"\\u8bb5\\u4f3c\\u95f2\\u5c45\\u65e5\\uff0c\\u5f92\\u95fb\\u6709\\u987a\\u98ce\\u3002\"]"', '诗', 'shi', '', NULL, '幸白鹿觀應制');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab1d190-a632-40f2-ac28-e43e91e72a56', '奉和聖製幸韋嗣立莊應制', '奉和圣制幸韦嗣立庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a39\\u8272\\u53c3\\u5dee\\u96b1\\u7fe0\\u5fae\\uff0c\\u6cc9\\u6d41\\u767e\\u5c3a\\u5411\\u7a7a\\u98db\\u3002\", \"\\u50b3\\u805e\\u6b64\\u8655\\u6295\\u7aff\\u4f4f\\uff0c\\u9042\\u4f7f\\u8332\\u8fb0\\u6248\\u8e55\\u6b78\\u3002\"]"', '"[\"\\u6811\\u8272\\u53c2\\u5dee\\u9690\\u7fe0\\u5fae\\uff0c\\u6cc9\\u6d41\\u767e\\u5c3a\\u5411\\u7a7a\\u98de\\u3002\", \"\\u4f20\\u95fb\\u6b64\\u5904\\u6295\\u7aff\\u4f4f\\uff0c\\u9042\\u4f7f\\u5179\\u8fb0\\u6248\\u8df8\\u5f52\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立莊應制');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbd1ab1-c266-4886-bc6d-9b4f23c58983', '奉和聖製過晉陽宮應制', '奉和圣制过晋阳宫应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u968b\\u904b\\u8207\\u5929\\u7d55\\uff0c\\u751f\\u9748\\u53ad\\u6c1b\\u660f\\u3002\", \"\\u8056\\u671f\\u5728\\u5be7\\u4e82\\uff0c\\u58eb\\u99ac\\u8208\\u592a\\u539f\\u3002\", \"\\u7acb\\u6975\\u842c\\u90a6\\u63a8\\uff0c\\u767b\\u5eb8\\u56db\\u6d77\\u5c0a\\u3002\", \"\\u6176\\u81ba\\u795e\\u6b66\\u5e1d\\uff0c\\u696d\\u4ed8\\u7687\\u66fe\\u5b6b\\u3002\", \"\\u7dec\\u6155\\u5c01\\u5510\\u9053\\uff0c\\u8ffd\\u60df\\u6b78\\u6c9b\\u9b42\\u3002\", \"\\u8a54\\u66f8\\u611f\\u5148\\u7fa9\\uff0c\\u5178\\u79ae\\u5de1\\u820a\\u85e9\\u3002\", \"\\u9ad8\\u6bbf\\u7db5\\u96f2\\u5408\\uff0c\\u6625\\u65d7\\u7965\\u98a8\\u7ffb\\u3002\", \"\\u7387\\u897f\\u898b\\u6c7e\\u6c34\\uff0c\\u5954\\u5317\\u7a7a\\u585e\\u57a3\\u3002\", \"\\u6b3e\\u66f2\\u7ae5\\u5152\\u4f50\\uff0c\\u4f9d\\u9072\\u6545\\u8001\\u8a00\\u3002\", \"\\u91cc\\u9812\\u6148\\u60e0\\u8cde\\uff0c\\u5bb6\\u53d7\\u5fa9\\u9664\\u6069\\u3002\", \"\\u4e0b\\u8f26\\u5d07\\u4e09\\u6559\\uff0c\\u5efa\\u7891\\u7576\\u4e5d\\u9580\\u3002\", \"\\u5b5d\\u601d\\u6566\\u81f3\\u7f8e\\uff0c\\u5104\\u8f09\\u5949\\u958b\\u5143\\u3002\"]"', '"[\"\\u968b\\u8fd0\\u4e0e\\u5929\\u7edd\\uff0c\\u751f\\u7075\\u538c\\u6c1b\\u660f\\u3002\", \"\\u5723\\u671f\\u5728\\u5b81\\u4e71\\uff0c\\u58eb\\u9a6c\\u5174\\u592a\\u539f\\u3002\", \"\\u7acb\\u6781\\u4e07\\u90a6\\u63a8\\uff0c\\u767b\\u5eb8\\u56db\\u6d77\\u5c0a\\u3002\", \"\\u5e86\\u81ba\\u795e\\u6b66\\u5e1d\\uff0c\\u4e1a\\u4ed8\\u7687\\u66fe\\u5b59\\u3002\", \"\\u7f05\\u6155\\u5c01\\u5510\\u9053\\uff0c\\u8ffd\\u60df\\u5f52\\u6c9b\\u9b42\\u3002\", \"\\u8bcf\\u4e66\\u611f\\u5148\\u4e49\\uff0c\\u5178\\u793c\\u5de1\\u65e7\\u85e9\\u3002\", \"\\u9ad8\\u6bbf\\u5f69\\u4e91\\u5408\\uff0c\\u6625\\u65d7\\u7965\\u98ce\\u7ffb\\u3002\", \"\\u7387\\u897f\\u89c1\\u6c7e\\u6c34\\uff0c\\u5954\\u5317\\u7a7a\\u585e\\u57a3\\u3002\", \"\\u6b3e\\u66f2\\u7ae5\\u513f\\u4f50\\uff0c\\u4f9d\\u8fdf\\u6545\\u8001\\u8a00\\u3002\", \"\\u91cc\\u9881\\u6148\\u60e0\\u8d4f\\uff0c\\u5bb6\\u53d7\\u590d\\u9664\\u6069\\u3002\", \"\\u4e0b\\u8f87\\u5d07\\u4e09\\u6559\\uff0c\\u5efa\\u7891\\u5f53\\u4e5d\\u95e8\\u3002\", \"\\u5b5d\\u601d\\u6566\\u81f3\\u7f8e\\uff0c\\u4ebf\\u8f7d\\u5949\\u5f00\\u5143\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製過晉陽宮應制');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb09e2ea-d8bf-4290-b034-f3249a088d56', '奉和姚令公溫湯舊館永懷故人盧公之作', '奉和姚令公温汤旧馆永怀故人卢公之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a39\\u5fb7\\u8c48\\u5b64\\u9081\\uff0c\\u964d\\u795e\\u826f\\u7add\\u51fa\\u3002\", \"\\u5049\\u8332\\u5eca\\u5edf\\u6968\\uff0c\\u8abf\\u5f7c\\u9e7d\\u6885\\u5be6\\u3002\", \"\\u6b63\\u6085\\u865e\\u5782\\u8209\\uff0c\\u7ffb\\u60b2\\u912d\\u50d1\\u5352\\u3002\", \"\\u540c\\u5fc3\\u4e0d\\u53ef\\u5fd8\\uff0c\\u4ea4\\u81c2\\u4f55\\u7232\\u5931\\u3002\", \"\\u6e05\\u8def\\u8377\\u524d\\u5e78\\uff0c\\u660e\\u6642\\u7a31\\u53f3\\u5f3c\\u3002\", \"\\u66fe\\u806f\\u91ce\\u5916\\u904a\\uff0c\\u5c1a\\u8a18\\u5e37\\u4e2d\\u5bc6\\u3002\", \"\\u65b0\\u615f\\u60c5\\u83ab\\u9063\\uff0c\\u820a\\u904a\\u8a5e\\u66f4\\u8ff0\\u3002\", \"\\u7a7a\\u4ee4\\u9084\\u8fb1\\u548c\\uff0c\\u9577\\u6b4e\\u77e5\\u97f3\\u65e5\\u3002\"]"', '"[\"\\u6811\\u5fb7\\u5c82\\u5b64\\u8fc8\\uff0c\\u964d\\u795e\\u826f\\u7add\\u51fa\\u3002\", \"\\u4f1f\\u5179\\u5eca\\u5e99\\u6862\\uff0c\\u8c03\\u5f7c\\u76d0\\u6885\\u5b9e\\u3002\", \"\\u6b63\\u60a6\\u865e\\u5782\\u4e3e\\uff0c\\u7ffb\\u60b2\\u90d1\\u4fa8\\u5352\\u3002\", \"\\u540c\\u5fc3\\u4e0d\\u53ef\\u5fd8\\uff0c\\u4ea4\\u81c2\\u4f55\\u4e3a\\u5931\\u3002\", \"\\u6e05\\u8def\\u8377\\u524d\\u5e78\\uff0c\\u660e\\u65f6\\u79f0\\u53f3\\u5f3c\\u3002\", \"\\u66fe\\u8054\\u91ce\\u5916\\u6e38\\uff0c\\u5c1a\\u8bb0\\u5e37\\u4e2d\\u5bc6\\u3002\", \"\\u65b0\\u6078\\u60c5\\u83ab\\u9063\\uff0c\\u65e7\\u6e38\\u8bcd\\u66f4\\u8ff0\\u3002\", \"\\u7a7a\\u4ee4\\u8fd8\\u8fb1\\u548c\\uff0c\\u957f\\u53f9\\u77e5\\u97f3\\u65e5\\u3002\"]"', '诗', 'shi', '', NULL, '奉和姚令公溫湯舊館永懷故人盧公之作');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('106f24fc-5222-4d03-984e-99a4f012f5a6', '和杜主簿春日有所思', '和杜主簿春日有所思', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u671d\\u4e0a\\u9ad8\\u6a13\\u4e0a\\uff0c\\u4fef\\u898b\\u6d1b\\u967d\\u964c\\u3002\", \"\\u6416\\u8569\\u5439\\u82b1\\u98a8\\uff0c\\u843d\\u82f1\\u7d1b\\u5df2\\u7a4d\\u3002\", \"\\u7f8e\\u4eba\\u4e0d\\u5171\\u6b64\\uff0c\\u82b3\\u597d\\u7a7a\\u6240\\u60dc\\u3002\", \"\\u652c\\u93e1\\u5875\\u7db2\\u6ecb\\uff0c\\u7576\\u7a97\\u82d4\\u861a\\u78a7\\u3002\", \"\\u7dec\\u61f7\\u5728\\u96f2\\u6f22\\uff0c\\u826f\\u9858\\u668c\\u6795\\u5e2d\\u3002\", \"\\u7ffb\\u4f3c\\u7121\\u898b\\u6642\\uff0c\\u5982\\u4f55\\u4e45\\u7232\\u5ba2\\u3002\"]"', '"[\"\\u671d\\u4e0a\\u9ad8\\u697c\\u4e0a\\uff0c\\u4fef\\u89c1\\u6d1b\\u9633\\u964c\\u3002\", \"\\u6447\\u8361\\u5439\\u82b1\\u98ce\\uff0c\\u843d\\u82f1\\u7eb7\\u5df2\\u79ef\\u3002\", \"\\u7f8e\\u4eba\\u4e0d\\u5171\\u6b64\\uff0c\\u82b3\\u597d\\u7a7a\\u6240\\u60dc\\u3002\", \"\\u63fd\\u955c\\u5c18\\u7f51\\u6ecb\\uff0c\\u5f53\\u7a97\\u82d4\\u85d3\\u78a7\\u3002\", \"\\u7f05\\u6000\\u5728\\u4e91\\u6c49\\uff0c\\u826f\\u613f\\u668c\\u6795\\u5e2d\\u3002\", \"\\u7ffb\\u4f3c\\u65e0\\u89c1\\u65f6\\uff0c\\u5982\\u4f55\\u4e45\\u4e3a\\u5ba2\\u3002\"]"', '诗', 'shi', '', NULL, '和杜主簿春日有所思');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92802726-3cdb-4107-a673-286b4e74c829', '餞郢州李使君', '饯郢州李使君', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u695a\\u6709\\u7ae0\\u83ef\\u81fa\\uff0c\\u9059\\u9059\\u96f2\\u5922\\u6fa4\\u3002\", \"\\u5fa9\\u805e\\u64c1\\u7b26\\u50b3\\uff0c\\u53ca\\u662f\\u6536\\u5716\\u7c4d\\u3002\", \"\\u4f73\\u653f\\u5728\\u96e2\\u4eba\\uff0c\\u80fd\\u8072\\u5bc4\\u4faf\\u4f2f\\u3002\", \"\\u96e2\\u61f7\\u6714\\u98a8\\u8d77\\uff0c\\u8a66\\u671b\\u79cb\\u9670\\u7a4d\\u3002\", \"\\u4e2d\\u8def\\u60bd\\u4ee5\\u5bd2\\uff0c\\u7fa3\\u5c71\\u9744\\u5c07\\u5915\\u3002\", \"\\u50b7\\u5fc3\\u804a\\u628a\\u8882\\uff0c\\u600a\\u60b5\\u9e92\\u9e9f\\u5ba2\\u3002\"]"', '"[\"\\u695a\\u6709\\u7ae0\\u534e\\u53f0\\uff0c\\u9065\\u9065\\u4e91\\u68a6\\u6cfd\\u3002\", \"\\u590d\\u95fb\\u62e5\\u7b26\\u4f20\\uff0c\\u53ca\\u662f\\u6536\\u56fe\\u7c4d\\u3002\", \"\\u4f73\\u653f\\u5728\\u79bb\\u4eba\\uff0c\\u80fd\\u58f0\\u5bc4\\u4faf\\u4f2f\\u3002\", \"\\u79bb\\u6000\\u6714\\u98ce\\u8d77\\uff0c\\u8bd5\\u671b\\u79cb\\u9634\\u79ef\\u3002\", \"\\u4e2d\\u8def\\u51c4\\u4ee5\\u5bd2\\uff0c\\u7fa4\\u5c71\\u972d\\u5c06\\u5915\\u3002\", \"\\u4f24\\u5fc3\\u804a\\u628a\\u8882\\uff0c\\u600a\\u6005\\u9e92\\u9e9f\\u5ba2\\u3002\"]"', '诗', 'shi', '', NULL, '餞郢州李使君');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce615b30-ecf1-4e72-ba3f-3623f2382fbf', '餞唐州高使君赴任', '饯唐州高使君赴任', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6c38\\u65e5\\u594f\\u6587\\u6642\\uff0c\\u6771\\u98a8\\u6416\\u8569\\u5915\\u3002\", \"\\u6d69\\u7136\\u601d\\u6a02\\u4e8b\\uff0c\\u7ffb\\u5fa9\\u991e\\u5f81\\u5ba2\\u3002\", \"\\u6dee\\u6c34\\u6625\\u6d41\\u6e05\\uff0c\\u695a\\u5c71\\u66ae\\u96f2\\u767d\\u3002\", \"\\u52ff\\u8a00\\u884c\\u8def\\u9060\\uff0c\\u6240\\u8cb4\\u5c08\\u57ce\\u4f2f\\u3002\"]"', '"[\"\\u6c38\\u65e5\\u594f\\u6587\\u65f6\\uff0c\\u4e1c\\u98ce\\u6447\\u8361\\u5915\\u3002\", \"\\u6d69\\u7136\\u601d\\u4e50\\u4e8b\\uff0c\\u7ffb\\u590d\\u996f\\u5f81\\u5ba2\\u3002\", \"\\u6dee\\u6c34\\u6625\\u6d41\\u6e05\\uff0c\\u695a\\u5c71\\u66ae\\u4e91\\u767d\\u3002\", \"\\u52ff\\u8a00\\u884c\\u8def\\u8fdc\\uff0c\\u6240\\u8d35\\u4e13\\u57ce\\u4f2f\\u3002\"]"', '诗', 'shi', '', NULL, '餞唐州高使君赴任');